-- Create PolyZones from zone definitions
local ActiveZones = {}

for _, zone in pairs(FishingZones) do
  ActiveZones[zone.name] = PolyZone:Create(zone.coords, {
    name = zone.name,
    debugPoly = false,
    debugGrid = false,
    minZ = zone.minZ,
    maxZ = zone.maxZ
  })
end

-- Check if player is inside any fishing zone
function GetPlayerFishingZone()
  for _, zone in pairs(ActiveZones) do
    if zone:isPointInside(GetEntityCoords(PlayerPedId())) then
      return true
    end
  end
  return false
end
